import {sortedIntervals} from './strategy-games.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,value)=>`<button class="btn" data-action="${action}" ${value===undefined?'':`data-value="${value}"`}>${label}</button>`;
export function strategyArt(g){return `<div class="strategy-mini" aria-hidden="true">${{courses:'0 → 1 → 3',intervals:'[1,3] [3,5]',rotated:'4 5 ⌕ 1 2',coins:'1 + 3 → 4',bits:'1 1 0 1'}[g.id]}</div>`;}
export function strategyBoard(g,s){
 const r=g.rounds[s.round];let body,title,subtitle,steps;
 if(g.id==='courses'){
  title='Complete a course with no prerequisites left.';subtitle='Arrows run from prerequisite to dependent course. Course numbers start at 0.';
  const pos=Array.from({length:r.n},(_,i)=>({x:260+160*Math.cos(i*2*Math.PI/r.n-Math.PI/2),y:130+90*Math.sin(i*2*Math.PI/r.n-Math.PI/2)}));
  body=`<svg class="course-viz" viewBox="0 0 520 260" role="img" aria-label="Prerequisite graph: ${r.edges.map(([a,b])=>b+' to '+a).join(', ')}"><defs><marker id="course-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#7e8f79"/></marker></defs>${r.edges.map(([a,b])=>{const p=pos[b],q=pos[a],d=Math.hypot(q.x-p.x,q.y-p.y),ux=(q.x-p.x)/d,uy=(q.y-p.y)/d;return `<line x1="${p.x+ux*26}" y1="${p.y+uy*26}" x2="${q.x-ux*30}" y2="${q.y-uy*30}" stroke="#7e8f79" stroke-width="2" opacity="${s.completed.includes(b)?'.15':'1'}" marker-end="url(#course-arrow)"/>`;}).join('')}${pos.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="24" fill="${s.completed.includes(i)?'#e7e8df':s.indegree[i]===0?'#b6d69c':'#dfd3ee'}"/><text x="${p.x}" y="${p.y+6}" text-anchor="middle">${i}</text>`).join('')}</svg><div class="course-options">${pos.map((_,i)=>`<button class="dp-cell ${s.completed.includes(i)?'finished':s.indegree[i]===0?'eligible':''}" data-action="course" data-value="${i}" ${s.done||s.completed.includes(i)?'disabled':''}><strong>Course ${i}</strong><span>${s.completed.includes(i)?'Complete':s.indegree[i]+' prerequisites left'}</span></button>`).join('')}</div><div class="queue-box"><strong>COMPLETION ORDER</strong><div>${s.completed.length?s.completed.join(' → '):'No courses completed yet'}</div></div><div class="controls">${s.done?'':button('cycle','No course is ready · cycle detected')}</div>`;
  steps=['Count incoming edges: these are the remaining prerequisites.','Complete any zero-indegree course and remove its outgoing edges. Several orders can be valid.','If unfinished courses remain with no ready course, a cycle blocks completion.'];
 }else if(g.id==='intervals'){
  title='Keep the earliest finish that fits.';subtitle='Intervals are sorted by end time. Sharing an endpoint is allowed.';
  const ordered=sortedIntervals(r),min=Math.min(...r.intervals.flat()),max=Math.max(...r.intervals.flat()),x=n=>50+420*(n-min)/(max-min);
  body=`<svg class="interval-viz" viewBox="0 0 520 ${ordered.length*60+30}" role="img" aria-label="Intervals sorted by end: ${ordered.map(o=>'['+o.pair.join(', ')+']').join('; ')}">${ordered.map(({pair:[a,b],index},i)=>{const y=35+i*60,color=i===s.index?'#e78958':s.kept.includes(i)?'#8eae7d':i<s.index?'#b8b8af':'#b6a4cf';return `<text x="4" y="${y+5}" class="axis-label">#${index}</text><line x1="${x(a)}" y1="${y}" x2="${x(b)}" y2="${y}" stroke="${color}" stroke-width="12" stroke-linecap="round" opacity="${i<s.index&&!s.kept.includes(i)?'.35':'1'}"/><text x="${x(a)}" y="${y+25}" text-anchor="middle">${a}</text><text x="${x(b)}" y="${y+25}" text-anchor="middle">${b}</text>`;}).join('')}</svg><p class="viz-caption">Orange: current interval · green: kept · faded: removed. # labels are original zero-based indices.</p><div class="record-row"><div>Last kept end<strong>${s.lastEnd??'—'}</strong></div><div>Removed<strong>${s.removed}</strong></div></div><div class="controls">${s.done?'':button('keep','Keep interval')+button('remove','Remove overlap')}</div>`;
  steps=['Sort by end time to consider the earliest finish first.','Keep an interval if its start is at least the last kept end. Otherwise remove it.','Count removals. An earlier finish leaves the most room for later intervals.'];
 }else if(g.id==='rotated'){
  title=s.left===s.right?'Select the minimum value.':'Which half still contains the minimum?';const mid=Math.floor((s.left+s.right)/2);
  subtitle=`Inclusive bounds [${s.left}, ${s.right}]. Compare nums[mid] = ${r.values[mid]} with nums[right] = ${r.values[s.right]}.`;
  body=`<div class="search-array">${r.values.map((v,i)=>`<button class="dp-cell ${i<s.left||i>s.right?'discarded':''} ${i===mid?'current':''}" data-action="minimum" data-value="${i}" ${s.done?'disabled':''}><small>index ${i}</small><strong>${v}</strong><span>${[i===s.left?'L':'',i===mid?'M':'',i===s.right?'R':''].filter(Boolean).join(' · ')||' '}</span></button>`).join('')}</div><p class="viz-caption">L = left · M = mid · R = right. Faded values are outside the search range.</p><div class="controls">${s.done||s.left===s.right?'':button('left','Keep left through mid · R = mid')+button('right','Keep after mid · L = mid + 1')}</div>`;
  steps=['If the middle value exceeds the rightmost value, the rotation point lies strictly after mid.','Otherwise keep mid: it might itself be the minimum.','When left equals right, return that value, not its index.'];
 }else if(g.id==='coins'){
  title='Build the cheapest way to the next amount.';subtitle=s.done?'Every subtotal is saved.':`Make amount ${s.index}. Choose a final coin using the fewest total coins, or mark this amount unreachable.`;
  body=`<div class="coin-table">${Array.from({length:r.amount+1},(_,i)=>`<div class="dp-cell ${i===s.index?'current':''}"><small>amount ${i}</small><strong>${i<s.dp.length?(s.dp[i]===Infinity?'∞':s.dp[i]):'?'}</strong><span>coins</span></div>`).join('')}</div><p class="viz-caption">dp[0] = 0 · ∞ = unreachable · coins can be used again.</p><div class="coin-options">${s.done?'':r.coins.map(c=>{const prev=s.index-c;return button('coin',`<strong>Use coin ${c}</strong><span>${prev<0?'Too large':`dp[${prev}] + 1 = ${Number.isFinite(s.dp[prev])?s.dp[prev]+1:'∞'}`}</span>`,c);}).join('')}</div><div class="controls">${s.done?'':button('coin','Mark unreachable',-1)}</div>`;
  steps=['Start with zero coins for amount 0. Build amounts in increasing order.','Try each coin as the last coin. Add 1 to the saved answer for the remaining amount. Tied best choices both work.','Keep the smallest count. If every remainder is unreachable, this amount is unreachable too.'];
 }else{
  title='Clear the rightmost 1.';subtitle='Bit indices start at 0 on the right. Each cleared set bit adds one to your count.';
  const binary=n=>n.toString(2).padStart(8,'0');
  body=`<div class="bit-strip">${[7,6,5,4,3,2,1,0].map(i=>`<button class="dp-cell ${(s.remaining>>i)&1?'eligible':''}" data-action="bit" data-value="${i}" ${s.done?'disabled':''}><small>bit ${i}</small><strong>${(s.remaining>>i)&1}</strong></button>`).join('')}</div><div class="bit-equation"><div><span>n</span><code>${binary(s.remaining)}</code></div>${s.remaining?`<div><span>n − 1</span><code>${binary(s.remaining-1)}</code></div><div class="bit-result"><span>n &amp; (n − 1)</span><code>${binary(s.remaining&(s.remaining-1))}</code></div>`:'<p>No set bits remain.</p>'}</div><div class="record-row"><div>Remaining number<strong>${s.remaining}</strong></div><div>Set bits counted<strong>${s.count}</strong></div></div>`;
  steps=['Find the lowest set bit: the rightmost 1.','Subtracting 1 flips that bit and every lower bit. AND with n clears just the lowest 1.','Repeat until n is zero. Your number of moves is the number of set bits.'];
 }
 const feedback=s.message?`<p class="feedback ${s.error?'error':''}">${esc(s.message)}${s.done?`<br><strong>${s.round+1===g.rounds.length?'Pattern unlocked. Opening your coding exercise…':'Loading the next round…'}</strong>`:''}</p>`:'';
 return `<div class="game-layout"><section class="game-board advanced-board"><div class="board-top"><span>ROUND ${s.round+1} OF ${g.rounds.length}</span><span class="target">${g.tag}</span></div><h2 class="instruction">${title}</h2><p class="subtext">${subtitle}</p>${body}<div id="game-feedback" aria-live="polite">${feedback}</div></section><aside class="explanation"><div class="icon">✳</div><h2>${g.concept}</h2><ol>${steps.map(t=>`<li>${t}</li>`).join('')}</ol><div class="divider">Explore each decision.<br>Wrong moves explain the invariant.</div></aside></div>`;
}
